import base64, io, itertools, json, pickle, time, hashlib
from pathlib import Path
import numpy as np
from harness import load_split, read_pred_csv
import harness.data as hd
ROOT=Path('/Users/saisreed/Desktop/Coding/house-edge-codex')
SHARED=Path('/Users/saisreed/Desktop/Coding/TamuDatathon26-PSAZZ/docs/sai/cache')
HERE=ROOT/'docs/sai/results'
configs=[dict(zip(('signal','pairs','hl_grid','prior','density'),x)) for x in itertools.product((0,1),repeat=5)]
def load_data():
    hd.CACHE=SHARED
    return load_split('train'),load_split('validation')
def load_validation():
    return load_data()[1]
def norm(p):
    p=np.maximum(np.asarray(p,float),1e-7)
    return p/p.sum(axis=-1,keepdims=True)
def load_features():
    d=json.loads((HERE/'W3W4_FEATURES.json').read_text())
    a=np.load(io.BytesIO(base64.b64decode(d['npz_base64'])),allow_pickle=False)
    out={'configs':configs,'metadata':d['metadata']}
    for tag in ('tr','va','roll'):
        out[tag]={k[len(tag)+1:]:a[k] for k in a.files if k.startswith(tag+'_')}
        out[tag]['names']=d['names']
        out[tag]['future_valid']=out[tag]['future_n']>=4
    return out
def cell_names(b,cfg):
    return list(b['names'])+[f'b3_{k}' for k in range(5)]+['b3_chosen_hl']
def cell_X(b,cfg):
    names=list(b['names']); X=b['X'].copy()
    for j,name in enumerate(names):
        if (not cfg['signal'] and (name.startswith('signal_') or name.startswith('interaction_'))) or (not cfg['pairs'] and name.startswith('pair_')):
            X[:,j]=0
        if name.startswith('freq_'):
            _,h,k=name.split('_'); X[:,j]=b['freq'][:,cfg['prior'],cfg['density'],(0 if h=='16' else 1),int(k)]
    # The two candidate memory grids are distinguishable via their fitted per-machine baseline.
    ci=configs.index(cfg)
    return np.column_stack([X,b['base'][ci],b['chosen_hl'][ci]])
def _screen():
    paths=list(SHARED.glob('w1_screen_*.pkl'))
    if not paths: raise RuntimeError('shared train-history lag screen missing; ask lead, do not rebuild')
    p=sorted(paths)[0]; d=pickle.loads(p.read_bytes())
    single={l:np.mean([v for (ty,k),v in d['single'].items() if k==l]) for l in range(1,17)}
    pair={ab:np.mean([v for (ty,a,b),v in d['pair'].items() if (a,b)==ab]) for ab in itertools.combinations(range(1,9),2)}
    pairs=sorted(sorted(pair,key=pair.get,reverse=True)[:3])
    lags=sorted(set([max(range(1,9),key=single.get)]+[k for ab in pairs for k in ab]))
    return lags,pairs,{'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'single_scores':single,'pair_scores':{str(k):v for k,v in pair.items()}}
def _priors(t,types,signals):
    tab=np.zeros((len(types),len(signals),5)); eps={}
    for i,g in enumerate(t.grid):
        c=np.array([(g==p).sum() for p in hd.PAY],float)
        a,b=types.index(t.mtype[i]),signals.index(int(t.signal[i]))
        tab[a,b]+=c
        eps.setdefault(str(t.episode[i]),np.zeros_like(tab))[a,b]+=c
    return tab,eps
def _one(g,cut,ty,sg,prior,lags,pairs):
    observed=np.flatnonzero(np.isfinite(g[:cut])); vals=g[observed]
    assert np.all(observed<cut)
    win=np.where(np.isfinite(g),2*(g>0)-1,0).astype(float)
    def design(tt, usepairs):
        tt=np.atleast_1d(tt); xx=[np.ones(len(tt))]
        for k in lags: xx.append(np.where(tt>=k,win[np.maximum(tt-k,0)],0))
        if usepairs:
            for a,b in pairs:xx.append(np.where(tt>=a,win[np.maximum(tt-a,0)],0)*np.where(tt>=b,win[np.maximum(tt-b,0)],0))
        return np.stack(xx,axis=1)
    old=observed<cut-40; oldfrac=old.sum()/max(cut-40,1); recentfrac=(~old).sum()/min(cut,40)
    density=np.where(old,np.clip(recentfrac/max(oldfrac,1e-3),1,20),1.)
    freq=np.empty((2,2,2,5)); ess=[]
    for pi in (0,1):
        for de in (0,1):
            for hi,hl in enumerate((16.,128.)):
                w=2.**(-(cut-1-observed)/hl)*(density if de else 1)
                c=np.array([w[vals==p].sum() for p in hd.PAY])
                freq[pi,de,hi]=(c+8*prior[pi])/(c.sum()+8)
                if pi==de==0:ess.append(w.sum()**2/max(w@w,1e-9))
    X=[];names=[]
    def add(n,v):names.append(n);X.append(float(v))
    for k in range(1,17):
        p=g[cut-k] if cut>=k else np.nan
        add('lag_win_'+str(k),0 if not np.isfinite(p) else 2*(p>0)-1)
        add('lag_missing_'+str(k),not np.isfinite(p))
        add('lag_payout_'+str(k),0 if not np.isfinite(p) else p)
        add('lag_log_'+str(k),0 if not np.isfinite(p) else np.log1p(p))
    for a,b in pairs:add(f'pair_{a}_{b}',win[cut-a]*win[cut-b] if cut>=max(a,b) else 0)
    for hi,h in enumerate((16,128)):
        for k in range(5):add(f'freq_{h}_{k}',freq[0,0,hi,k])
        add(f'ess_{h}',ess[hi])
    add('obs_recent',recentfrac);add('obs_old',oldfrac);add('obs_count',len(observed));add('obs_cutoff',cut)
    for h in (4,8,16,40):
        z=vals[observed>=cut-h]
        for label,v in [('mean',z.mean() if len(z) else 0),('logmean',np.log1p(z).mean() if len(z) else 0),('var',z.var() if len(z) else 0),('missing',1-len(z)/h)]:add(f'moment_{h}_{label}',v)
    for thr in (1,5,20):
        tt=observed[vals>=thr];add('since_'+str(thr),cut-int(tt[-1]) if len(tt) else cut+1)
    a,b=freq[0,0];m=(a+b)/2
    add('drift_tv',np.abs(a-b).sum()/2);add('drift_l2',((a-b)**2).sum());add('drift_jsd',.5*((a*np.log(a/m)).sum()+(b*np.log(b/m)).sum()))
    w=(vals>0).astype(float);cs=np.cumsum(w-w.mean());add('cusum_range',np.ptp(cs)/np.sqrt(max(len(w),1)))
    bas=np.empty((32,5));hls=np.empty(32)
    # Fit each distinct (pairs, memory grid, density) once; signal only changes feature columns.
    fits={}
    ticks=observed[observed>=max(lags+list(pairs[0]))];y=(g[ticks]>0).astype(float)
    for pp,hh,dd in itertools.product((0,1),repeat=3):
        A=design(ticks,pp);q=design(cut,pp)[0];pen=np.eye(A.shape[1])*20;pen[0,0]=1e-6
        grid=(1e9,128.,64.,32.,16.) if hh==0 else (1e9,128.,32.,8.)
        def fit(mask,ref,h):
            weight=2.**(-(ref-1-ticks[mask])/h)
            if dd:
                # infer density within this fit's available history, never using held-out outcomes
                tt=ticks[mask];c=max(ref-40,1);of=(tt<c).sum()/c;rf=(tt>=c).sum()/min(ref,40)
                weight*=np.where(tt<c,np.clip(rf/max(of,1e-3),1,20),1)
            aa=A[mask];return np.linalg.solve(aa.T@(weight[:,None]*aa)+pen,aa.T@(weight*y[mask]))
        tr=ticks<cut-40;te=~tr;hl=1e9
        if len(observed)>=.6*cut and tr.sum()>=30 and te.sum()>=10:
            errors=[np.mean((np.clip(A[te]@fit(tr,cut-40,h),0,1)-y[te])**2) for h in grid]
            hl=grid[int(np.argmin(errors))]
        pw=np.clip(q@fit(np.ones(len(ticks),bool),cut,hl),.005,.995)
        fits[pp,hh,dd]=(pw,hl)
    for ci,cfg in enumerate(configs):
        pw,hl=fits[cfg['pairs'],cfg['hl_grid'],cfg['density']]
        sev=freq[cfg['prior'],cfg['density'],1,1:].copy();sev/=sev.sum()
        bas[ci]=np.r_[1-pw,pw*sev];hls[ci]=np.log2(min(hl,1024))
    return np.array(X),names,freq,bas,hls

def build(smoke=False):
    t,v=load_data();lags,pairs,screen=_screen();types=sorted(set(t.mtype));signals=sorted(set(int(x) for x in t.signal));tab,byep=_priors(t,types,signals)
    allarrays={}; names=None;counts={}
    for tag,s in [('tr',t),('va',v),('roll',t)]:
        rows=[]
        for i,cut in enumerate(s.cutoff):
            if smoke and i>=32:break
            ticks=[int(cut)] if tag!='roll' else [int(k) for k in range(100,int(cut)-1,32) if np.isfinite(s.grid[i,k])]
            for c in ticks:rows.append((i,c))
        N=len(rows);counts[tag]=N; xs=[];fs=[];bs=[];hs=[];meta={k:[] for k in ('episode','mtype','signal','cutoff','outcome','condition','future','future_n','machine','source_row')}
        for i,c in rows:
            tt,sg=types.index(s.mtype[i]),signals.index(int(s.signal[i]));z=tab.copy()
            if tag!='va':z-=byep[str(s.episode[i])]
            prior=[(z[tt].sum(0)+.5)/(z[tt].sum()+2.5),(z[tt,sg]+.5)/(z[tt,sg].sum()+2.5)]
            x,names,f,b,h=_one(s.grid[i],c,tt,sg,prior,lags,pairs)
            for ty in types:x=np.r_[x,float(s.mtype[i]==ty)]
            for si in signals:x=np.r_[x,float(int(s.signal[i])==si)]
            for ty in types:
                for si in signals:x=np.r_[x,float(s.mtype[i]==ty and int(s.signal[i])==si)]
            xs.append(x);fs.append(f);bs.append(b);hs.append(h)
            future=s.grid[i,c:min(c+32,int(s.cutoff[i]))] if tag=='roll' else np.array([])
            fcnt=np.array([(future==p).sum() for p in hd.PAY]);fq=(fcnt+.5)/(fcnt.sum()+2.5)
            vals=dict(episode=str(s.episode[i]),mtype=str(s.mtype[i]),signal=int(s.signal[i]),cutoff=c,outcome=int(s.grid[i,c]) if tag=='roll' else int(s.outcome[i]),condition=str(s.condition[i]),future=fq,future_n=int(fcnt.sum()),machine=str(s.machine[i]),source_row=i)
            for k in meta:meta[k].append(vals[k])
        X=np.array(xs)
        fullnames=names+[f'type_{ty}' for ty in types]+[f'signal_{si}' for si in signals]+[f'interaction_{ty}_{si}' for ty in types for si in signals]
        # Episode features use peers at the same pseudo-cutoff only. Missing peer visits remain unknown.
        F=np.array(fs);peer=np.zeros((N,7));groups={}
        for j,(i,c) in enumerate(rows):groups.setdefault((str(s.episode[i]),c),[]).append(j)
        for inds in groups.values():
            for j in inds:
                ii=[k for k in inds if k!=j]
                if ii:
                    drift=F[ii,0,0,0]-F[ii,0,0,1]
                    peer[j]=np.r_[drift.mean(0),np.abs(drift).sum(1).mean()/2,len(ii)]
        allarrays[tag+'_X']=np.column_stack([X,peer]).astype('float32');allarrays[tag+'_freq']=F.astype('float32');allarrays[tag+'_base']=np.moveaxis(np.array(bs),1,0).astype('float32');allarrays[tag+'_chosen_hl']=np.array(hs).T.astype('float32')
        for k,val in meta.items():allarrays[tag+'_'+k]=np.array(val)
        print(tag,N,'rows',flush=True)
    out=io.BytesIO();np.savez_compressed(out,**allarrays)
    doc={'metadata':{'version':1,'counts':counts,'lags':lags,'pairs':pairs,'screen':screen,'configs':configs,'feature_rule':'strict tick<cutoff; NaN unknown; train priors leave-one-episode-out; no validation truth used','rolling_ticks':'observed ticks from100 to cutoff-1 step32','future_window':32},'names':fullnames+[f'peer_residual_{k}' for k in range(5)]+['peer_mean_tv','peer_count'],'npz_base64':base64.b64encode(out.getvalue()).decode()}
    if not smoke:(HERE/'W3W4_FEATURES.json').write_text(json.dumps(doc))
    return doc
